widget.body:
(() => {
  const general = document.getElementById("xframe-input-general_interest");
  const specific = document.getElementById("xframe-input-specific_opportunity");
  if (!(general instanceof HTMLTextAreaElement) || !(specific instanceof HTMLTextAreaElement)) return;

  const generalControl = general.closest(".xframe-input-control");
  const specificControl = specific.closest(".xframe-input-control");
  if (!(generalControl instanceof HTMLElement) || !(specificControl instanceof HTMLElement)) return;

  const sync = () => {
    const hasSpecific = specific.value.trim().length > 0;
    general.disabled = hasSpecific;
    generalControl.classList.toggle("is-expanded", !hasSpecific);
    generalControl.classList.toggle("is-collapsed", hasSpecific);
    specificControl.classList.toggle("is-expanded", hasSpecific);
    specificControl.classList.toggle("is-collapsed", !hasSpecific);
    general.rows = hasSpecific ? 2 : 14;
    specific.rows = hasSpecific ? 14 : 2;
  };

  specific.addEventListener("input", sync);
  // Template hydration may fill values after this script runs.
  document.getElementById("xframe")?.addEventListener("xframe:slidechange", sync);
  queueMicrotask(sync);
  setTimeout(sync, 0);
  sync();
})();

