      font: 650 .72rem/1.2 var(--sans);
      letter-spacing: .12em;
      text-transform: uppercase;
      color: var(--accent);
    }
    h1 {
      margin: 0;
      font: 700 1.85rem/1.15 var(--sans);
      letter-spacing: -.02em;
    }
    .doc-tagline {
      margin: .4rem 0 0;
      font: 600 1.05rem/1.3 var(--sans);
      color: var(--body);
      text-wrap: balance;
