    .summary {
      margin: 0 0 .85rem;
      color: var(--body);
      text-wrap: pretty;
    }
    .summary:last-of-type { margin-bottom: 1.35rem; }
    h2 {
      margin: 1.55rem 0 .4rem;
      font: 700 .92rem/1.25 var(--sans);
      text-transform: uppercase;
      letter-spacing: .07em;
      color: var(--accent);
    }
    .section-note {
      margin: 0 0 .75rem;
      color: var(--muted);
      font: 400 .88rem/1.4 var(--sans);
    }
    .role {
      margin: 0 0 .95rem;
      padding-bottom: .85rem;
      border-bottom: 1px solid var(--rule);
      break-inside: avoid;
    }
    .role:last-child { margin-bottom: 0; border-bottom: 0; padding-bottom: 0; }
    .role-heading {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;
      gap: .25rem .85rem;
    }
    .role-title {
      font: 700 1.02rem/1.3 var(--sans);
      color: var(--ink);
    }
    .role-period {
      font: 600 .88rem/1.35 var(--sans);
      color: var(--muted);
      white-space: nowrap;
    }
    ul {
      margin: .4rem 0 0;
      padding-left: 1.15rem;
    }
    li {
      margin: .28rem 0;
      color: var(--body);
      text-wrap: pretty;
    }
    .timeline {
      margin: 0;
      padding: 0;
      list-style: none;
    }
    .timeline-item {
      display: grid;
      grid-template-columns: 7.75rem 1fr;
      gap: .35rem .85rem;
      margin: 0 0 1.05rem;
      padding: 0 0 .95rem;
      border-bottom: 1px solid var(--rule);
      break-inside: avoid;
    }
    .timeline-item:last-child {
      margin-bottom: 0;
      padding-bottom: 0;
      border-bottom: 0;
    }
    .timeline-period {
      color: var(--muted);
      font: 650 .86rem/1.4 var(--sans);
      white-space: nowrap;
    }
    .timeline-body { min-width: 0; }
    .timeline-org {
      font: 700 .98rem/1.3 var(--sans);
      color: var(--ink);
    }
    .timeline-title {
      color: var(--body);
      font: 600 .95rem/1.35 var(--sans);
    }
    .timeline-detail {
      margin-top: .1rem;
      color: var(--muted);
      font-size: .88em;
    }
    .timeline-description {
      margin: .4rem 0 0;
      color: var(--body);
      font-size: .95em;
      text-wrap: pretty;
    }
    .timeline-achievements {
      margin: .4rem 0 0;
      padding-left: 1.1rem;
    }
    .timeline-achievements li {
      margin: .22rem 0;
      color: var(--body);
      font-size: .93em;
    }
    .closing {
      margin: 1.5rem 0 0;
      color: var(--body);
      font-style: italic;
      text-wrap: pretty;
    }
    .footer {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      justify-content: space-between;
      gap: .5rem 1rem;
      margin-top: 1.75rem;
