<body>
  <main>
    <header class="doc-header">
      <p class="doc-kicker">Résumé extract</p>
      <h1>{{ person.name | e }}</h1>
      {% if tagline %}<p class="doc-tagline">{{ tagline | e }}</p>{% endif %}
      <p class="extracted-on">Extracted <time data-extracted-on datetime="">—</time></p>
    </header>

    {% if summary_text %}
    {% for para in summary_text.split("\n\n") %}
    {% if para | trim %}
    <p class="summary">{{ para | trim | e }}</p>
    {% endif %}
    {% endfor %}
    {% endif %}

    {% if s.roles %}
    <h2>Selected relevant experience</h2>
    <p class="section-note">Emphasized for this conversation from the presentation evidence.</p>
    {% for role in s.roles %}
    <section class="role">
      <div class="role-heading">
        <div class="role-title">{{ role.title | e }}</div>
        {% if role.period %}<div class="role-period">{{ role.period | e }}</div>{% endif %}
      </div>
      {% if role.bullets %}
      <ul>
        {% for bullet in role.bullets %}
        <li>{{ bullet | e }}</li>
        {% endfor %}
      </ul>
      {% endif %}
    </section>
    {% endfor %}
    {% endif %}

    {% for profile in data.profile %}
    {% set omit = profile.resume_omit_ids | default([]) %}
    {% set start_id = profile.resume_start_id | default("") %}
    {% set ns = namespace(done=false) %}
    <h2>Career at a glance</h2>
    <p class="section-note">Complete employment chronology with role descriptions and key achievements — not filtered by this request.</p>
    <ul class="timeline">
      {% for we in profile.work_experiences %}
      {% if not ns.done and we.work_experience_id not in omit %}
      <li class="timeline-item">
        <div class="timeline-period">{{ we.start_date[:4] | e }}–{% if we.end_date %}{{ we.end_date[:4] | e }}{% else %}present{% endif %}</div>
        <div class="timeline-body">
          <div class="timeline-org">{{ we.company_name | e }}</div>
          {% if we.job_title %}<div class="timeline-title">{{ we.job_title | e }}</div>{% endif %}
          {% if we.location %}<div class="timeline-detail">{{ we.location | e }}</div>{% endif %}
          {% if we.description %}<p class="timeline-description">{{ we.description | e }}</p>{% endif %}
          {% if we.achievements %}
          <ul class="timeline-achievements">
            {% for achievement in we.achievements %}
            {% if achievement.text %}<li>{{ achievement.text | e }}</li>{% endif %}
            {% endfor %}
          </ul>
          {% endif %}
        </div>
      </li>
      {% if start_id and we.work_experience_id == start_id %}{% set ns.done = true %}{% endif %}
      {% endif %}
      {% endfor %}
    </ul>
    {% endfor %}

    {% if s.closing %}
    <p class="closing">{{ s.closing | e }}</p>
    {% endif %}

    <footer class="footer">
      <a href="{{ runtime.invite.short_url | e }}">View the interactive résumé</a>
      <span class="footer-date">Extracted <time data-extracted-on datetime="">—</time></span>
    </footer>

    <aside class="about-aside">
      <h2>About this résumé</h2>
      <p>
        This document is a context-specific projection of a structured career model.
        The underlying career timeline and source information are canonical; AI is used
        to select and emphasize the experience most relevant to this reader's context.
      </p>
      <p class="generated-with">Generated with xFrame.</p>
    </aside>
  </main>
  <script>
    (function () {
      var locale = {{ (target_locale | default("en-US")) | tojson }};
      var when = new Date();
      var iso = when.toISOString().slice(0, 10);
      var label = when.toLocaleDateString(locale, {
        year: "numeric",
        month: "long",
        day: "numeric"
      });
      document.querySelectorAll("[data-extracted-on]").forEach(function (el) {
        el.setAttribute("datetime", iso);
        el.textContent = label;
      });
    })();
  </script>
</body>
</html>

